val items = Channel<Item>()            // rendezvous: no buffer to grow

suspend fun consume() {
    for (item in items) {              // suspends until a producer sends
        handle(item)
    }
}

suspend fun produce(item: Item) {
    items.send(item)                   // suspends until a consumer receives
}

