private val lock = Object()
private val q = ArrayDeque<Int>()

fun take(): Int = synchronized(lock) {
    while (q.isEmpty()) (lock as Object).wait()   // release + park + re-acquire
    q.removeFirst()
}

fun put(v: Int) = synchronized(lock) {
    q.addLast(v)
    (lock as Object).notifyAll()                  // change, then wake the set
}
